"""Original ANCA-associated vasculitis questions with late-2026 safety context."""
from create_rheum_large_vessel import rows,q,V,IM,ref
A=ref('EULAR AAV management: 2022 update','https://ard.bmj.com/content/83/1/30')
K=ref('KDIGO 2024 AAV guideline and amendments','https://kdigo.org/guidelines/antineutrophilic-cytoplasmic-antibody-anca-associated-vasculitis-aav/')

q('Chronic destructive sinusitis, otitis, cavitating pulmonary nodules and rapidly progressive glomerulonephritis most strongly suggest which disorder?', 'Granulomatosis with polyangiitis',[
 ('Microscopic polyangiitis','MPA causes small-vessel capillaritis/GN but does not usually produce the same granulomatous destructive upper-airway/nodular phenotype.'),('Polyarteritis nodosa','PAN affects medium arteries and does not characteristically cause glomerulonephritis or pulmonary capillaritis.'),('Eosinophilic granulomatosis with polyangiitis','Asthma, eosinophilia and an eosinophilic phenotype would be stronger clues.')],
 'Recognize the upper-airway–lung–kidney pattern','**GPA can combine granulomatous respiratory disease with pauci-immune glomerulonephritis.**',['PR3-ANCA commonly supports the diagnosis but is not mandatory in every case.','Infection, malignancy and other inflammatory disorders can mimic nodules and systemic disease.'], '**Assess renal and pulmonary urgency.**',['Obtain urine sediment, kidney function, antigen-specific ANCA testing and appropriate tissue.','Do not delay necessary treatment in a rapidly deteriorating organ-threatening presentation.'],[['GPA','Granulomatous airway/lung phenotype'],['MPA','Nongranulomatous capillaritis'],['PAN','Medium-artery disease without typical GN']],[A,K])

q('A patient has diffuse alveolar hemorrhage and pauci-immune crescentic GN, MPO-ANCA positivity and no granulomatous upper-airway disease. Which phenotype is most likely?', 'Microscopic polyangiitis',[
 ('Polyarteritis nodosa','PAN does not typically produce pulmonary capillaritis and glomerulonephritis.'),('IgA vasculitis','This is an immune-complex disease with IgA-dominant deposits rather than a pauci-immune pattern.'),('Anti-GBM disease','This is associated with linear GBM immunostaining and anti-GBM antibodies.')],
 'A pulmonary-renal syndrome requires a mechanism-based diagnosis','**MPA commonly causes necrotizing small-vessel disease and pauci-immune GN.**',['MPO-ANCA is frequent but serotype and disease name are not perfectly interchangeable.','Anti-GBM overlap can occur and changes management.'], '**Test relevant antibodies and obtain tissue when feasible.**',['Evaluate oxygenation and bleeding severity.','Exclude infection and other causes before or alongside immune treatment.'],[['MPA','Pauci-immune GN/capillaritis'],['Anti-GBM','Linear antibody pattern'],['IgA vasculitis','IgA immune deposits']],[A,K],style='clinical_scenario')

q('Adult-onset asthma, marked eosinophilia, migratory pulmonary infiltrates and mononeuritis multiplex most strongly suggest which diagnosis?', 'Eosinophilic granulomatosis with polyangiitis',[
 ('GPA','Its granulomatous airway phenotype is different and marked asthma/eosinophilia is less typical.'),('MPA','This lacks the defining eosinophilic/asthmatic pattern.'),('Hypereosinophilic syndrome as established without further assessment','HES is an important differential, but the asthma-plus-vasculitic neuropathy phenotype supports EGPA.')],
 'Connect eosinophilic airway disease to systemic vasculitis','**EGPA can combine eosinophilic inflammation with necrotizing vasculitis.**',['Only a subset is ANCA positive.','Drug reactions, parasites, allergic bronchopulmonary disease and clonal eosinophilia can be mimics.'], '**Assess cardiac, neurological, renal and pulmonary involvement.**',['Cardiac disease can be severe even in ANCA-negative EGPA.','Treatment intensity depends on organ threat, not eosinophil count alone.'],[['Asthma/eosinophilia','Key phenotype'],['Neuropathy','Potential vasculitic organ injury'],['ANCA negative','Does not exclude EGPA']],[A],style='clinical_scenario')

q('Which renal biopsy pattern is most characteristic of ANCA-associated glomerulonephritis?', 'Necrotizing crescentic GN with little or no immune deposition',[
 ('Linear IgG staining along the GBM','This suggests anti-GBM disease.'),('IgA-dominant mesangial deposits','This suggests IgA nephropathy/vasculitis in the appropriate context.'),('Full-house immune-complex staining','This raises a lupus-associated pattern among other possibilities.')],
 'Pauci-immune describes the immunofluorescence pattern','**AAV typically causes necrosis and crescents with sparse immune deposits.**',['A biopsy also defines chronicity and potentially reversible injury.','Rare mixed patterns require careful interpretation.'], '**Combine pathology with serology and the systemic phenotype.**',['ANCA-negative pauci-immune disease exists.','Assess for an anti-GBM overlap when clinically relevant.'],[['AAV','Pauci-immune'],['Anti-GBM','Linear IgG'],['Lupus','Immune-complex full-house pattern']],[K])

q('Which is the preferred initial laboratory approach when GPA or MPA is suspected?', 'High-quality antigen-specific assays for PR3-ANCA and MPO-ANCA',[
 ('ANA alone','This does not directly investigate the characteristic AAV antigens.'),('An indirect fluorescence pattern without antigen-specific interpretation in every case','Modern recommendations support high-quality PR3/MPO assays as primary tests in appropriate suspected disease.'),('RF alone','RF does not diagnose AAV.')],
 'Test the relevant antigens in the right clinical setting','**PR3 and MPO specificity is more informative than an isolated shorthand c-ANCA/p-ANCA label.**',['A positive result is not diagnostic without compatible disease.','Infection, medications and other disorders can produce ANCA positivity.'], '**Use tissue and organ assessment when needed.**',['Negative testing does not rule out every limited or seronegative vasculitis.','Avoid indiscriminate testing in low-probability presentations.'],[['PR3/MPO','Antigen specificity'],['Clinical context','Determines predictive value'],['Biopsy','Can establish the injury pattern']],[A])

q('A patient with previously controlled AAV has a rising ANCA titer but stable symptoms, urine and kidney function. What is the best response?', 'Review and monitor clinically rather than automatically escalating immunosuppression from the titer alone',[
 ('Give cyclophosphamide for every isolated titer rise','A biomarker change alone does not establish a clinical relapse.'),('Stop all follow-up because serology has no possible prognostic information','Serology can add context, but should not dominate the decision.'),('Diagnose renal relapse without repeat urine or kidney assessment','Objective organ evaluation is needed.')],
 'Risk information is not the same as active organ injury','**ANCA trends can contribute to assessment but do not independently define relapse.**',['Relapse decisions rely on symptoms, examination and organ-specific studies.','Unnecessary escalation adds infection and drug toxicity.'], '**Look carefully for early renal, pulmonary or other activity.**',['Arrange a follow-up plan appropriate to the risk and trajectory.','Investigate new objective abnormalities promptly.'],[['Titer rise','Potential risk signal'],['Clinical relapse','Requires disease assessment'],['Treatment','Not dictated by titer alone']],[A,K],style='clinical_scenario')

q('Which regimen is a standard induction approach for organ-threatening GPA/MPA?', 'Glucocorticoids with rituximab or cyclophosphamide',[
 ('Hydroxychloroquine alone','This is inadequate for organ-threatening AAV.'),('Azathioprine alone as immediate induction for rapidly progressive GN','Azathioprine is more commonly a maintenance option and is not adequate sole induction here.'),('Colchicine alone','This does not control severe necrotizing vasculitis.')],
 'Induce remission promptly in organ-threatening disease','**Rituximab or cyclophosphamide with an appropriate glucocorticoid strategy is a principal induction framework.**',['The regimen depends on severity, relapse history, kidney function, fertility and previous exposure.','Reduced glucocorticoid approaches can limit infectious harm in appropriate patients.'], '**Coordinate treatment with organ support and prevention.**',['Assess infection before and during treatment.','Plan PJP prevention, HBV screening and drug-specific monitoring.'],[['Induction','Control active severe disease'],['Maintenance','Prevent relapse after response'],['Supportive care','Organ support and infection prevention']],[A,K])

q('In relapsing organ-threatening GPA after previous cyclophosphamide exposure, which induction agent is often favored if suitable?', 'Rituximab',[
 ('Hydroxychloroquine','This is not adequate induction for severe GPA.'),('Azathioprine alone','This is not the usual severe-relapse induction choice.'),('Low-dose methotrexate alone despite severe renal disease','Methotrexate is unsuitable for this organ-threatening renal context.')],
 'Prior exposure and relapse phenotype affect the induction choice','**Rituximab is often favored for severe relapsing GPA/MPA.**',['It avoids additional cyclophosphamide cumulative gonadal and malignancy toxicity.','Individual renal severity and prior treatment response still matter.'], '**Assess B-cell-depletion safety before treatment.**',['Review HBV status, immunoglobulins, infection risk and vaccination.','Do not assume rituximab alone removes the need for an overall induction and taper plan.'],[['Relapse','Rituximab often preferred'],['Prior CYC','Cumulative toxicity matters'],['Safety','HBV and immune status']],[A,K],style='clinical_scenario')

q('Which treatment is commonly preferred for maintenance of GPA/MPA remission after successful induction?', 'Scheduled rituximab in an appropriate patient',[
 ('Continued daily cyclophosphamide indefinitely','Cumulative toxicity makes this unsuitable as routine indefinite maintenance.'),('Stopping all treatment immediately after the first improvement','Relapse prevention is usually required.'),('Long-term high-dose prednisone alone','This adds toxicity and is not the preferred maintenance framework.')],
 'Maintenance is a planned phase of treatment','**Rituximab is a preferred maintenance option in many GPA/MPA patients.**',['Azathioprine or selected alternatives can be appropriate.','Duration depends on relapse risk, phenotype, tolerance and patient preference.'], '**Monitor for both relapse and treatment-related immune compromise.**',['Review infections and immunoglobulins during repeated B-cell depletion.','Structural damage and persistent symptoms do not always mean active relapse.'],[['Induction','Initial disease control'],['Maintenance','Relapse prevention'],['CYC','Avoid indefinite cumulative exposure']],[A,K])

q('What is the current role of plasma exchange in AAV?', 'Consider it selectively in severe renal or hypoxemic alveolar hemorrhage presentations and in anti-GBM overlap, rather than routinely for every case',[
 ('Mandatory treatment for every ANCA-positive patient','ANCA positivity alone is not an indication.'),('Proven to reduce death or ESKD in all PEXIVAS patients','The trial did not demonstrate that universal primary-outcome benefit.'),('Never appropriate under any circumstances after PEXIVAS','Guidelines retain selected high-risk and overlap contexts.')],
 'Interpret a negative overall trial without erasing selected clinical roles','**Plasma exchange is not routine AAV therapy for all patients.**',['KDIGO considers severe renal dysfunction/rapid deterioration and hypoxemic alveolar hemorrhage as settings for individualized consideration.','Anti-GBM overlap is an important separate indication context.'], '**Weigh potential renal benefit against infection and procedural risks.**',['Assess severity and competing diagnoses urgently.','Use the current amended guideline rather than a slogan that it always or never helps.'],[['Routine AAV','No universal indication'],['Selected severe presentations','Consider individually'],['Anti-GBM overlap','Changes the approach']],[K,ref('PEXIVAS original trial','https://www.nejm.org/doi/full/10.1056/NEJMoa1803537')])

q('What receptor does avacopan antagonize?', 'C5a receptor',[
 ('IL-5 receptor alpha','This is targeted by benralizumab.'),('CD20','This is targeted by rituximab.'),('IL-6 receptor','This is targeted by tocilizumab.')],
 'Separate a pharmacological mechanism from current suitability','**Avacopan blocks C5a receptor signaling.**',['Older AAV guidelines discussed a steroid-sparing role.','By late 2026 major efficacy-data integrity and serious hepatic safety concerns changed the regulatory landscape.'], '**Do not treat a mechanism question as a current prescribing endorsement.**',['FDA proposed withdrawal and EMA recommended revocation; the UK suspended initiation in new patients.','Check the current local status and alternatives before any use decision.'],[['Mechanism','C5a receptor'],['Historical guideline role','Must be read with later evidence'],['Late-2026 context','Major regulatory restrictions/concerns']],[ref('FDA proposed Tavneos withdrawal: April 2026','https://www.fda.gov/drugs/drug-alerts-and-statements/cder-proposes-withdraw-approval-tavneos'),ref('MHRA avacopan review: September 2026','https://www.gov.uk/government/news/mhra-concludes-review-of-avacopan-vifor-following-reassessment-of-benefit-risk-balance')])

q('An older source recommends avacopan routinely for steroid sparing in AAV. Which late-2026 update is essential?', 'Efficacy-data integrity and serious liver-injury concerns have led to major withdrawal/revocation actions or proposals, requiring current jurisdiction-specific review',[
 ('All regulatory bodies have confirmed the pivotal data are fully reliable','Regulators explicitly raised data integrity and efficacy concerns.'),('Only a minor rash warning was added with no change in benefit-risk assessment','The changes involve efficacy and serious, sometimes fatal, hepatic injury.'),('A 2024 guideline permanently overrides all later regulatory decisions','Later evidence and regulatory actions materially change clinical use.')],
 'Current evidence can supersede an older treatment recommendation','**FDA proposed withdrawal in April 2026 because valid efficacy demonstration could no longer be concluded.**',['EMA recommended revocation in June 2026.','MHRA suspended new-patient use from September 2026 with a managed transition for existing patients.'], '**Describe each jurisdiction accurately rather than saying one global legal status applies.**',['Patients already treated need specialist-supervised review and transition planning.','Continue appropriate liver monitoring and investigate symptoms of hepatic injury.'],[['FDA','Withdrawal proposed'],['EMA','Revocation recommended'],['UK','New-patient initiation suspended']],[ref('FDA Tavneos withdrawal proposal','https://www.fda.gov/drugs/drug-alerts-and-statements/cder-proposes-withdraw-approval-tavneos'),ref('EMA Tavneos referral','https://www.ema.europa.eu/en/medicines/human/referrals/tavneos'),ref('MHRA avacopan benefit-risk review','https://www.gov.uk/government/news/mhra-concludes-review-of-avacopan-vifor-following-reassessment-of-benefit-risk-balance')],style='clinical_scenario')

q('A patient receives rituximab or cyclophosphamide with substantial glucocorticoids for AAV. Which infection prevention is particularly relevant?', 'Pneumocystis jirovecii prophylaxis when indicated by the regimen and patient risk',[
 ('Routine long-term antifungal therapy for every patient regardless of risk','This is not an equivalent universal prophylaxis rule.'),('No prophylaxis because immune disease itself prevents infection','Induction treatment increases serious infection risk.'),('Antibacterial prophylaxis only after the first proven PJP episode','Primary prevention is relevant in high-risk regimens.')],
 'Prevent a predictable complication of intensive immune treatment','**PJP prevention is recommended in relevant AAV induction settings.**',['TMP-SMX is commonly used, with alternatives for intolerance or contraindication.','Renal function, potassium, blood counts and interacting medicines affect selection.'], '**Include prevention in the initial prescription plan.**',['Review vaccines, TB/HBV risk and other infection precautions as appropriate.','Do not ignore cytopenia or renal toxicity during prophylaxis.'],[['High-risk immune treatment','PJP prevention'],['TMP-SMX','Common option'],['Safety review','Renal, marrow and interaction factors']],[A,K])

q('A patient has relapsing EGPA with asthma and sinonasal activity but no active organ-threatening vasculitis. Which biological option directly neutralizes IL-5?', 'Mepolizumab',[
 ('Benralizumab','This targets IL-5 receptor alpha rather than the IL-5 ligand.'),('Rituximab','This targets CD20.'),('Tocilizumab','This targets the IL-6 receptor.')],
 'Match eosinophil-directed mechanism to the drug','**Mepolizumab neutralizes IL-5 and has evidence in relapsing/refractory non-organ-threatening EGPA.**',['Benralizumab is another eosinophil-directed option with an adult EGPA indication in relevant jurisdictions.','These therapies do not replace severe-organ induction when major vasculitic injury is active.'], '**Assess whether relapse is eosinophilic airway disease, systemic vasculitis or both.**',['Review glucocorticoid burden and prior response.','Monitor cardiac and neurological disease according to the phenotype.'],[['Mepolizumab','IL-5 ligand'],['Benralizumab','IL-5 receptor alpha'],['Severe vasculitis','Different induction needs']],[A,ref('MANDARA randomized EGPA trial','https://doi.org/10.1056/NEJMoa2311155')],style='clinical_scenario')

q('An ANCA-negative EGPA patient develops chest pain, elevated troponin and new ventricular dysfunction. Which complication must be evaluated urgently?', 'Eosinophilic myocarditis/cardiac involvement',[
 ('A benign asthma symptom that cannot affect the heart','EGPA can cause life-threatening cardiac disease.'),('An exclusion of EGPA because ANCA is negative','Many EGPA patients are ANCA negative.'),('A diagnosis of isolated coronary atherosclerosis without further assessment','Ischemia is a differential, but eosinophilic cardiac involvement requires urgent evaluation.')],
 'ANCA negativity does not protect the heart','**Cardiac involvement can be a major organ-threatening EGPA manifestation.**',['Use ECG, biomarkers, echocardiography and cardiac MRI as appropriate.','Coronary disease and other myocarditis causes may coexist or mimic it.'], '**Treat the patient as an urgent cardiac and vasculitic problem.**',['Provide hemodynamic/arrhythmia care and specialist-directed induction.','Do not use airway symptom control as proof of systemic remission.'],[['Troponin/dysfunction','Organ injury evidence'],['ANCA negative','Does not exclude EGPA cardiac disease'],['Urgency','Cardiac support plus disease treatment']],[A],style='clinical_scenario')

q('A patient develops purpura, glomerulonephritis and high MPO-ANCA while taking hydralazine. Which diagnosis should be considered?', 'Drug-associated ANCA vasculitis',[
 ('Uncomplicated drug-induced lupus as certain despite crescentic GN','Hydralazine can cause a severe vasculitic renal phenotype beyond classic mild drug-induced lupus.'),('Primary PAN as proven by MPO-ANCA','PAN is not defined by MPO-ANCA and does not classically cause GN.'),('A benign antibody finding that cannot cause organ injury','The renal syndrome requires urgent evaluation.')],
 'A drug history can identify the vasculitic trigger','**Hydralazine is associated with ANCA vasculitis and overlapping autoantibody patterns.**',['Anti-histone, ANA and other antibodies can coexist.','Renal biopsy and clinical assessment determine the injury mechanism.'], '**Stop the suspected culprit and assess organ threat.**',['Severe disease may still require induction immunosuppression.','Document the exposure and avoid casual re-exposure.'],[['Hydralazine','Recognized trigger'],['GN/purpura','Potential severe vasculitis'],['Treatment','Withdrawal plus severity-directed care']],[A,K],style='clinical_scenario')

